seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"):
            continue
        seq += line.strip()

comp = str.maketrans("ACGT","TGCA")
rc = seq.translate(comp)[::-1]

start_codons = ["ATG","GTG","TTG"]
stop_codons = ["TAA","TAG","TGA"]

def find_orfs(s, strand, min_aa=30):
    orfs=[]
    L=len(s)
    for frame in range(3):
        i=frame
        while i < L-2:
            cod=s[i:i+3]
            if cod in start_codons:
                j=i
                while j < L-2:
                    c2=s[j:j+3]
                    if c2 in stop_codons:
                        if (j+3-i)//3 >= min_aa:
                            orfs.append((i,j+3,strand,frame,(j+3-i)//3, s[i:i+3], c2))
                        break
                    j+=3
                else:
                    # no stop until end
                    pass
                i=j+3 if j+3 < L else i+3
            else:
                i+=3
    return orfs

for minaa in [50, 100, 150]:
    print("=== min %d aa ===" % minaa)
    for s,strand in [(seq,'+'),(rc,'-')]:
        orfs=find_orfs(s,strand,minaa)
        orfs.sort(key=lambda x:-x[4])
        for o in orfs:
            print(strand, "start=%d end=%d frame=%d aa=%d startcodon=%s stop=%s"%(o[0],o[1],o[3],o[4],o[5],o[6]))
