# Find repeated k-mers (k=20..40) appearing more than once
def find_repeats(s,kmin=15,kmax=60):
    seen={}
    for k in range(kmin,kmax+1):
        d={}
        for i in range(len(s)-k+1):
            sub=s[i:i+k]
            d.setdefault(sub,[]).append(i)
        for sub,pos in d.items():
            if len(pos)>1:
                seen.setdefault(sub,pos)
    # keep maximal non-redundant
    subs=sorted(seen, key=lambda x:-len(x))
    return subs, seen

subs,seen=find_repeats(seq)
print("Top repeated substrings:")
for sub in subs[:25]:
    print(len(sub), seen[sub], sub)
